import { z } from 'zod';
import { baseFindAllOptionsSchema, staticBaseFindAllOptionsSchema, findBaseOptionsSchema, staticBaseFindOptionsSchema, } from './resource-options.js';
export const WebhookSchema = z.object({
    id: z.number().meta({
        label: 'ID',
        description: 'Identifier of the webhook.',
    }),
    type: z.string().meta({
        label: 'Type',
    }),
    url: z.string().meta({
        label: 'URL',
    }),
    provider: z.string().meta({
        label: 'Provider',
    }),
    status: z.string().meta({
        label: 'Status',
    }),
    createdAt: z.date().meta({
        label: 'Created At',
    }),
    updatedAt: z.date().meta({
        label: 'Updated At',
    }),
});
export const WebhookCreateSchema = z.object({
    type: z.string().meta({
        label: 'Type',
    }),
    url: z.string().url().meta({
        label: 'URL',
    }),
    provider: z.string().optional().meta({
        label: 'Provider',
    }),
    status: z.enum(['active', 'inactive']).optional().meta({
        label: 'Status',
    }),
    workspaceId: z.coerce.number().optional().meta({
        label: 'Workspace Id',
    }),
    eventId: z.coerce.number().nullable().optional().meta({
        label: 'Event Id',
    }),
});
const webhooksFindAllSchema = {
    filter: z
        .object({
        eventId: z.coerce.number().optional(),
    })
        .optional(),
    sort: z.never().optional(),
    include: z.never().optional(),
};
export const webhooksFindAllOptionsSchema = baseFindAllOptionsSchema.extend(webhooksFindAllSchema);
export const webhooksFindOptionsSchema = findBaseOptionsSchema.extend({});
export const staticWebhooksFindAllOptionsSchema = staticBaseFindAllOptionsSchema.extend(webhooksFindAllSchema);
export const staticWebhooksFindOptionsSchema = staticBaseFindOptionsSchema.extend({});
export const staticWebhooksCreateOptionsSchema = staticBaseFindAllOptionsSchema.extend({});
